CREATE FUNCTION public.max_nonalnum_run(text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $_$
    select coalesce(max(length(m[1])), 0)
    from regexp_matches($1, '([^a-z0-9]+)', 'g') as m
$_$;

CREATE FUNCTION public.max_repeated_alnum_run(text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $_$
    select coalesce(max(length(m[1])), 0)
    from regexp_matches($1, '(([a-z0-9])\2*)', 'g') as m
$_$;

